globalThis.FURG_READING_DATA=[{"id":"papeis-avulsos","title":"Papéis avulsos","author":"Machado de Assis","year":1882,"genre":"Contos","tagline":"A aparência de prestígio sob a lente da ironia.","summary":["Publicado em 1882, Papéis avulsos reúne doze narrativas de formas variadas: diálogo, relato, carta, paródia e história de experiências aparentemente científicas. Não há um protagonista nem um enredo contínuo. Na advertência, Machado sugere que a diversidade do volume encobre parentescos. Uma leitura possível dessa unidade está na investigação das vaidades, dos interesses e das convenções que orientam a vida social.","Em O alienista, o médico Simão Bacamarte instala a Casa Verde em Itaguaí e altera sucessivamente seus critérios para identificar a loucura. Em Teoria do medalhão, um pai ensina ao filho como conquistar prestígio por meio da aparência de importância e da renúncia a ideias próprias. Já em O espelho, Jacobina associa sua percepção de identidade à posição de alferes e à farda que a representa.","Os demais contos ampliam essa investigação: O segredo do bonzo expõe a fabricação da crença; A sereníssima República transforma aranhas e eleições numa sátira política; Na arca parodia o relato bíblico ao introduzir uma disputa por propriedade. O humor não oferece uma solução moral simples. O leitor precisa confrontar os discursos das personagens com seus interesses e resultados. As narrativas dialogam com a crítica realista das relações sociais, mas também usam o insólito, a fantasia e a paródia para tornar visíveis mecanismos de poder."],"themes":[{"title":"Prestígio e aparência","text":"Títulos, fardas e fórmulas de erudição podem valer mais socialmente que a competência ou a autonomia intelectual. O reconhecimento público participa da construção da identidade."},{"title":"Verdade e autoridade","text":"Quem define a loucura, a cura ou a legitimidade de uma eleição? Os contos interrogam a autoridade dos discursos que pretendem encerrar essas questões."},{"title":"Ironia e formas literárias","text":"Machado imita linguagens reconhecíveis — conselho paterno, conferência, escritura bíblica — e cria um descompasso entre a solenidade do discurso e os interesses que ele encobre."}],"focus":["Compare o que uma personagem afirma com o efeito concreto de suas ações; a ironia pode surgir desse intervalo.","Identifique quem conta cada história. Papéis avulsos alterna vozes e formas; a voz de uma personagem não equivale automaticamente à posição do autor.","Relacione O espelho, Teoria do medalhão e O segredo do bonzo pela dependência do olhar alheio, sem apagar as diferenças de enredo e de construção."],"pitfalls":["Reduzir o volume a O alienista: são doze narrativas, e suas diferenças também importam.","Ler os conselhos do pai em Teoria do medalhão ou as teorias de Bacamarte como ensinamentos defendidos literalmente por Machado."],"sources":[{"title":"USP — Biblioteca Brasiliana: edição de 1882 e sumário","url":"https://digital.bbm.usp.br/handle/bbm/4774"},{"title":"Biblioteca Nacional / Cervantes: registro da edição original","url":"https://www.cervantesvirtual.com/obra/papeis-avulsos--0/"},{"title":"Wikisource — texto integral em domínio público, edição de 1882","url":"https://pt.wikisource.org/wiki/Pap%C3%A9is_avulsos"}],"questions":[{"id":"papeis-avulsos-1","prompt":"Em O alienista, os critérios de Simão Bacamarte para separar razão e loucura mudam ao longo da narrativa. Qual efeito crítico essa oscilação produz?","options":["Confirma que as primeiras internações estavam corretas e que a ciência apenas aperfeiçoou sua aplicação.","Expõe o risco de uma autoridade transformar hipóteses instáveis em decisões que controlam a vida coletiva.","Demonstra que a população consegue eliminar definitivamente o poder médico por meio da revolta.","Defende que qualquer diferença de comportamento deve ser explicada exclusivamente pela moral religiosa.","Estabelece um diagnóstico final seguro, que o leitor deve aplicar às demais personagens."],"answerIndex":1,"explanation":"A instabilidade das classificações contrasta com a força institucional de Bacamarte. A sátira questiona a pretensão de certeza e seus efeitos de poder, sem apresentar um manual alternativo de diagnóstico.","skill":"Ironia e poder"},{"id":"papeis-avulsos-2","prompt":"O pai de Janjão, em Teoria do medalhão, recomenda evitar ideias próprias e cultivar fórmulas de boa aceitação pública. Lido ironicamente, esse conselho denuncia:","options":["A impossibilidade de transmitir conhecimentos entre gerações de uma mesma família.","A preferência do filho por atividades artísticas pouco valorizadas pelo pai.","A dificuldade de um intelectual original para encontrar uma profissão adequada.","Um modelo de ascensão social que recompensa a conformidade e a aparência de importância.","Uma defesa da pesquisa científica como principal fonte de reconhecimento público."],"answerIndex":3,"explanation":"O conselho assume a forma de orientação prática, mas seu conteúdo revela o esvaziamento intelectual necessário ao prestígio. O leitor distingue o projeto do pai da crítica construída pelo conto.","skill":"Ironia"},{"id":"papeis-avulsos-3","prompt":"Em O espelho, a imagem de Jacobina recupera nitidez quando ele veste a farda de alferes. O episódio permite interpretar a farda como:","options":["Um suporte material da identidade social que passou a organizar a percepção que ele tem de si.","Uma prova de que a identidade individual permanece intacta diante de qualquer reconhecimento externo.","Um instrumento de ascensão econômica que substitui completamente a carreira militar.","Uma indicação de que o espelho havia sido consertado durante a ausência das demais pessoas.","Um recurso que desfaz a hierarquia entre o alferes e os escravizados da propriedade."],"answerIndex":0,"explanation":"A farda concentra a posição e os elogios que sustentavam a chamada alma exterior de Jacobina. Seu uso recompõe a imagem percebida, ligando identidade pessoal e reconhecimento social.","skill":"Símbolo e identidade"},{"id":"papeis-avulsos-4","prompt":"Em O segredo do bonzo, a promessa de narizes metafísicos convence pessoas que tiveram o nariz retirado. A situação satiriza principalmente:","options":["A incapacidade da ficção de representar acontecimentos que não possam ser observados.","A recusa de todas as personagens a aceitar qualquer argumento de uma autoridade.","A superioridade da experiência sensorial sobre toda crença, reconhecida pelos doentes.","A substituição da medicina pela religião como solução necessariamente eficaz.","A força da persuasão e do prestígio discursivo para produzir uma crença socialmente aceita."],"answerIndex":4,"explanation":"A convicção dos desnarigados persiste apesar da ausência de um órgão visível. A experiência extrema a distância entre existência material e opinião sustentada pela autoridade e pela retórica.","skill":"Discurso e aparência"},{"id":"papeis-avulsos-5","prompt":"Na arca imita o estilo de uma narrativa bíblica, mas faz os filhos de Noé brigarem pela divisão de terras e de um rio antes de saírem da embarcação. Esse contraste sugere:","options":["Que a abundância de terras elimina a competição sempre que existe parentesco.","Que o texto pretende corrigir um erro geográfico presente no relato do dilúvio.","Que a promessa de recomeço não impede a reprodução da cobiça e da violência humanas.","Que a disputa nasce apenas da escassez real de território disponível após o dilúvio.","Que a linguagem solene confirma a justiça das reivindicações de todos os irmãos."],"answerIndex":2,"explanation":"A luta ocorre quando ainda há um mundo a repartir. A paródia contrapõe a promessa de concórdia à antecipação da propriedade e da rivalidade, problematizando a ideia de regeneração automática.","skill":"Paródia e intertextualidade"},{"id":"papeis-avulsos-6","prompt":"Em A sereníssima República, alterações sucessivas no saco usado nas eleições das aranhas não eliminam as fraudes. Qual leitura melhor explica a sátira?","options":["Os procedimentos podem ser adaptados pelos interesses que pretendem controlar, frustrando a promessa de correção meramente formal.","A ausência de regras é apresentada como a única causa da corrupção e como o ideal político do narrador.","O sorteio é demonstrado como garantia suficiente de igualdade em qualquer sociedade.","As aranhas recusam a organização política porque preferem manter suas decisões individuais.","A narrativa mostra que a sofisticação de uma regra impede definitivamente sua manipulação."],"answerIndex":0,"explanation":"Cada ajuste provoca novas formas de contornar o procedimento. A sucessão põe em dúvida a crença de que uma reforma técnica, por si só, elimina interesses e práticas fraudulentas.","skill":"Alegoria política"},{"id":"papeis-avulsos-7","prompt":"O desfecho de A chinela turca revela que a aventura de Duarte ocorreu em sonho durante a leitura de um drama pelo major Lopo Alves. Esse recurso:","options":["Confirma a existência de uma investigação policial independente da experiência de Duarte.","Elimina a relação entre o tédio inicial e as situações extraordinárias da aventura.","Transforma a história num testemunho documental sobre práticas criminosas da época.","Reorganiza retrospectivamente o enredo e aproxima a imaginação do ouvinte das convenções melodramáticas.","Prova que o major contou deliberadamente toda a aventura como parte de sua autobiografia."],"answerIndex":3,"explanation":"A revelação obriga a reler os episódios fantásticos a partir da situação inicial. O sonho mobiliza convenções do melodrama e cria uma fuga imaginária diante da longa leitura imposta a Duarte.","skill":"Estrutura narrativa"},{"id":"papeis-avulsos-8","prompt":"Em Verba testamentária, o narrador explica os atos de Nicolau recorrendo a uma suposta doença orgânica. Por que essa explicação deve ser lida com atenção crítica?","options":["Porque retira do conto qualquer ligação entre comportamento individual e vida pública.","Porque a linguagem de diagnóstico recobre atitudes de inveja e competição, produzindo uma explicação também irônica.","Porque demonstra que todos os atos de Nicolau são conscientemente planejados para beneficiar os outros.","Porque o narrador apresenta exames que encerram de forma objetiva a interpretação da personagem.","Porque a doença impede que Nicolau participe de qualquer acontecimento social ou político."],"answerIndex":1,"explanation":"A moldura patológica apresenta como enfermidade a dificuldade de suportar o destaque alheio. A ironia alcança tanto as condutas de Nicolau quanto a pretensão explicativa da linguagem usada para descrevê-las.","skill":"Narrador e ironia"},{"id":"papeis-avulsos-9","prompt":"A advertência de Papéis avulsos sugere parentesco entre textos aparentemente dispersos. Qual procedimento de leitura melhor explora essa proposta?","options":["Reconstruir uma única cronologia em que todas as personagens se encontram.","Atribuir a todas as narrativas o mesmo narrador de O alienista.","Ignorar a variedade formal para procurar uma conclusão moral idêntica em cada conto.","Ler os contos como registros autobiográficos sucessivos da juventude de Machado.","Comparar como diferentes formas narrativas investigam prestígio, interesse e autoridade."],"answerIndex":4,"explanation":"A unidade não exige continuidade de personagens ou de acontecimentos. A comparação temática e formal permite perceber afinidades entre os contos sem convertê-los artificialmente num romance.","skill":"Composição da coletânea"},{"id":"papeis-avulsos-10","prompt":"Uma leitura de Papéis avulsos afirma que a presença de sonhos, aranhas organizadas politicamente e experiências insólitas impede qualquer crítica da sociedade. Qual objeção é mais consistente?","options":["A crítica social depende de excluir toda situação improvável de uma narrativa.","As passagens fantásticas devem ser lidas como acontecimentos históricos comprovados.","O insólito pode tornar mais visíveis, por deslocamento e exagero, mecanismos reconhecíveis da vida social.","A fantasia anula a ironia, mas preserva exclusivamente o valor moral dos conselhos paternos.","O volume abandona os conflitos humanos sempre que utiliza uma forma não documental."],"answerIndex":2,"explanation":"O deslocamento ficcional não exclui a referência social. A sociedade das aranhas ou a experiência dos narizes metafísicos exageram mecanismos políticos e discursivos que o leitor pode reconhecer fora do conto.","skill":"Realismo e fantasia"}],"color":"#526e65"},{"id":"hora-da-estrela","title":"A hora da estrela","author":"Clarice Lispector","year":1977,"genre":"Novela / romance breve","tagline":"Uma vida invisibilizada e o impasse de quem tenta narrá-la.","summary":["Publicado em 1977, A hora da estrela acompanha Macabéa, jovem alagoana que vive no Rio de Janeiro e trabalha como datilógrafa. Sua rotina de poucos recursos inclui o rádio, o trabalho precário e relações em que ela recebe pouco acolhimento. O namoro com Olímpico de Jesus termina quando ele se interessa por Glória, colega de Macabéa. O vínculo amoroso também deixa perceber o desejo de ascensão social do rapaz.","Essa trajetória não chega ao leitor por uma voz neutra: Rodrigo S.M., narrador e escritor fictício, expõe dúvidas, interrupções e dificuldades para contar a vida de alguém socialmente distante dele. Sua insistente presença cria um segundo eixo narrativo: a própria elaboração do livro. Aproximações e gestos de compaixão convivem com julgamentos e incômodo; por isso, suas afirmações sobre a protagonista exigem leitura crítica.","Indicada por Glória, Macabéa visita madama Carlota, que anuncia um futuro promissor. Ela sai da consulta tomada pela expectativa de outra vida, mas é atropelada e morre. O contraste entre a esperança recém-formada e o desfecho sustenta a ironia trágica do título. A obra articula desigualdade, solidão e desejo de existir com uma investigação sobre o poder e os limites da linguagem. Assim, o drama social não elimina a reflexão existencial: ambos atravessam a relação entre protagonista, narrador e leitor."],"themes":[{"title":"Invisibilidade social","text":"O cotidiano de Macabéa permite examinar quem recebe atenção, afeto e oportunidades. Sua exclusão envolve trabalho, gênero, migração e relações pessoais."},{"title":"Metalinguagem","text":"A história mostra seu próprio processo de construção. As hesitações de Rodrigo tornam a escrita um problema, em vez de um caminho transparente até a personagem."},{"title":"Esperança e desamparo","text":"A promessa da cartomante abre uma expectativa de futuro interrompida pelo atropelamento. A ironia aproxima o desejo de reconhecimento da persistência do abandono."}],"focus":["Separe Clarice, autora real, de Rodrigo S.M., narrador fictício. As opiniões dele podem revelar limites e contradições da própria voz narrativa.","Observe a Rádio Relógio e a publicidade: informações e imagens circulam, mas seu consumo não garante participação social ou domínio dos códigos urbanos.","Leia o título em relação ao desfecho, sem transformar a morte em reparação da desigualdade."],"pitfalls":["Tratar o livro como um relato linear contado apenas do ponto de vista de Macabéa.","Substituir a leitura do livro pela adaptação cinematográfica: a mediação de Rodrigo e a reflexão sobre a escrita são decisivas no texto literário."],"sources":[{"title":"Instituto Moreira Salles — A hora da estrela, por Clarisse Fukelman","url":"https://site.claricelispector.ims.com.br/livro/a-hora-da-estrela/"},{"title":"Editora Rocco — sinopse da obra","url":"https://rocco.com.br/produto/a-hora-da-estrela/"},{"title":"USP — Por ruas que uma mulher precisa andar: uma leitura de Clarice Lispector","url":"https://revistas.usp.br/ls/article/view/682"},{"title":"SciELO / Galáxia — As múltiplas faces de Clarice","url":"https://www.scielo.br/j/gal/a/vCNjsFz4RFVbK55zZjQJBXG/?lang=pt"},{"title":"UFG — Clarice Lispector: uma narrativa que borda o sujeito do desamparo","url":"https://repositorio.bc.ufg.br/tede/bitstreams/8aea63ec-de88-4403-bc5d-7b057eadbf65/download"}],"questions":[{"id":"hora-da-estrela-1","prompt":"As interrupções de Rodrigo S.M. para discutir como contará a história de Macabéa produzem qual efeito central?","options":["Transformam a protagonista em autora consciente do texto lido.","Retiram do livro qualquer referência às condições materiais da personagem.","Expõem a construção narrativa e a dificuldade de representar alguém socialmente distante de quem escreve.","Garantem que a interpretação do narrador seja imparcial em todas as situações.","Organizam a trajetória da protagonista numa sucessão estritamente cronológica."],"answerIndex":2,"explanation":"A hesitação não é apenas um atraso no enredo: torna a representação um problema do próprio livro. O leitor acompanha simultaneamente a vida narrada e o esforço contraditório de narrá-la.","skill":"Metalinguagem"},{"id":"hora-da-estrela-2","prompt":"Um leitor toma os julgamentos de Rodrigo sobre a pouca importância de Macabéa como conclusões definitivas do romance. Qual cuidado essa leitura deixa de observar?","options":["O narrador é uma criação ficcional cujas avaliações também podem ser interrogadas pela obra.","Rodrigo narra somente acontecimentos dos quais participou fisicamente ao lado da protagonista.","A protagonista concorda expressamente com todas as análises feitas sobre sua condição social.","O romance não apresenta uma voz narrativa reconhecível em primeira pessoa.","Clarice elimina qualquer distância entre a autora real e o escritor inventado."],"answerIndex":0,"explanation":"Uma voz que descreve a exclusão pode reproduzir seus critérios. A forte presença de Rodrigo convida a examinar sua posição, em vez de converter automaticamente suas avaliações em juízos finais da autora.","skill":"Narrador e autoria"},{"id":"hora-da-estrela-3","prompt":"Macabéa acompanha a Rádio Relógio, que oferece a hora certa e informações variadas. No conjunto do romance, esse hábito permite perceber:","options":["A formação de um projeto intelectual que lhe assegura ascensão profissional.","A passagem de Macabéa a uma posição de controle sobre os meios de comunicação.","A substituição do trabalho precário por uma atuação profissional no rádio.","A circulação de fragmentos de conhecimento sem garantia de integração à vida social.","O completo isolamento da personagem de qualquer produto da cultura urbana."],"answerIndex":3,"explanation":"O acesso a mensagens não equivale a acesso às oportunidades ou ao entendimento dos códigos sociais. O rádio participa de sua vida, mas não desfaz a distância entre informação recebida e inclusão.","skill":"Cultura e exclusão"},{"id":"hora-da-estrela-4","prompt":"Ao relacionar a troca de Macabéa por Glória às ambições de Olímpico, qual interpretação é mais adequada?","options":["O episódio separa a vida amorosa de qualquer avaliação de vantagens materiais.","O desejo de ascender atravessa também a escolha amorosa e a valorização das pessoas.","A origem nordestina de Olímpico garante sua solidariedade com a condição de Macabéa.","Glória representa a recusa de todos os valores associados ao sucesso urbano.","A decisão de Olímpico decorre unicamente de uma incompatibilidade entre crenças religiosas."],"answerIndex":1,"explanation":"A relação afetiva aparece atravessada pela busca de posição social. A proximidade regional não impede a reprodução de hierarquias, e o romance não idealiza a solidariedade entre pessoas igualmente marginalizadas.","skill":"Relações sociais"},{"id":"hora-da-estrela-5","prompt":"A consulta a madama Carlota é seguida pelo atropelamento de Macabéa. O efeito dessa sequência depende sobretudo:","options":["Da confirmação literal de todas as previsões da cartomante.","Da revelação de que Macabéa conhecia antecipadamente o acidente.","Da interrupção definitiva das reflexões do narrador antes do desfecho.","Do abandono de qualquer relação entre expectativa e acontecimentos.","Do choque entre um futuro desejável recém-anunciado e sua brusca interrupção."],"answerIndex":4,"explanation":"A promessa modifica a expectativa de Macabéa e prepara o contraste trágico. A sequência intensifica o desamparo justamente quando a possibilidade de uma vida diferente passa a ocupar a personagem.","skill":"Ironia trágica"},{"id":"hora-da-estrela-6","prompt":"Por que a associação entre o título A hora da estrela e o desfecho não deve ser lida como uma vitória social convencional de Macabéa?","options":["Porque o título deixa de ter qualquer relação com a protagonista depois da consulta.","Porque a morte realiza integralmente seu projeto de carreira artística.","Porque a visibilidade ligada à morte não repara a vida marcada pelo abandono.","Porque o narrador afirma que sua personagem nunca existiu dentro da ficção.","Porque o atropelamento encerra o livro com a plena inclusão econômica da personagem."],"answerIndex":2,"explanation":"O brilho do título é ambivalente e cruel quando associado ao instante final. Reconhecer a personagem nesse limite não equivale a proporcionar-lhe o reconhecimento e as condições que faltaram durante a vida.","skill":"Título e desfecho"},{"id":"hora-da-estrela-7","prompt":"A convivência entre miséria material e reflexões sobre linguagem e existência permite concluir que o romance:","options":["Abandona a crítica social sempre que Rodrigo discute seu processo de escrita.","Acrescenta um comentário filosófico que não interfere na forma de narrar.","Reduz a situação de Macabéa a uma experiência universal sem localização histórica.","Apresenta a pobreza apenas como pretexto para uma discussão estética independente.","Articula a exclusão concreta ao problema de reconhecer e representar outra pessoa."],"answerIndex":4,"explanation":"O impasse da escrita nasce também da distância social entre narrador e protagonista. Separar rigidamente forma e realidade empobrece uma narrativa na qual essa relação constitui parte do conflito.","skill":"Forma e sociedade"},{"id":"hora-da-estrela-8","prompt":"Rodrigo manifesta aproximação e compaixão por Macabéa, mas também impaciência e julgamentos depreciativos. Essa oscilação:","options":["Torna visível a ambivalência da representação e impede uma posição inteiramente confortável para narrador e leitor.","Comprova que a protagonista controla todos os comentários feitos pelo narrador.","Estabelece a compaixão como garantia de que nenhuma hierarquia é reproduzida na escrita.","Mostra que o romance alterna dois narradores chamados Rodrigo, com posições incompatíveis.","Resolve o conflito de classe ao apagar a distância entre os universos das personagens."],"answerIndex":0,"explanation":"A aproximação não elimina o poder de quem nomeia e descreve. A ambivalência permite examinar como a vontade de dar visibilidade pode conviver com a reprodução de distâncias e preconceitos.","skill":"Ética da representação"},{"id":"hora-da-estrela-9","prompt":"Em um dia em que não vai trabalhar, Macabéa fica sozinha no quarto e dança. Em relação à sua rotina, o episódio pode ser lido como:","options":["Uma ruptura econômica definitiva com o emprego e com a vida precária.","Uma demonstração de que a personagem desconhece qualquer experiência de alegria.","Um instante de experiência de si que introduz uma diferença dentro de seu cotidiano limitado.","A comprovação de que os projetos de ascensão social de Olímpico foram realizados.","A passagem imediata da personagem à carreira artística que sempre planejara."],"answerIndex":2,"explanation":"O momento de intimidade e movimento evita reduzir Macabéa à ausência absoluta de desejos e experiências. Essa abertura pontual não elimina a precariedade que estrutura sua vida.","skill":"Subjetividade e cotidiano"},{"id":"hora-da-estrela-10","prompt":"Um resumo da obra relata somente o trabalho, o namoro e o atropelamento de Macabéa. Que dimensão decisiva essa seleção deixa em segundo plano?","options":["Uma investigação policial conduzida por Olímpico ao longo do romance.","A história do escritor fictício que transforma o ato de narrar em parte do conflito.","Uma disputa de herança responsável pela mudança da protagonista para São Paulo.","A alternância de cartas escritas por Glória e madama Carlota.","A trajetória de Macabéa como narradora de suas memórias após a morte."],"answerIndex":1,"explanation":"O enredo inclui o drama da escrita de Rodrigo. Omiti-lo pode fornecer a sequência básica de acontecimentos, mas apaga a dimensão metalinguística que organiza a experiência de leitura.","skill":"Estrutura narrativa"}],"color":"#98674f"},{"id":"olhos-dagua","title":"Olhos d'água","author":"Conceição Evaristo","year":2014,"genre":"Contos","tagline":"Memória, afetos e vidas negras em uma prosa de força poética.","summary":["Publicado em 2014, Olhos d'água reúne quinze contos, e não capítulos de um romance. Diferentes personagens negras, sobretudo mulheres, vivem situações atravessadas pela desigualdade, pelo racismo e pela violência. Infância, trabalho, maternidade, sexualidade e envelhecimento aparecem por perspectivas variadas. A diversidade dessas experiências impede reduzir a coletânea à trajetória de uma única protagonista ou a uma imagem uniforme da mulher negra.","No conto que dá nome ao livro, uma filha tenta recordar a cor dos olhos da mãe. Essa pergunta aparentemente simples movimenta lembranças da infância, da fome e dos cuidados maternos. Os olhos associados à água aproximam lágrimas, memória e ancestralidade, convertendo uma busca individual em reconhecimento de pertencimento. Esse enredo pertence ao conto de abertura: as demais narrativas têm personagens e situações próprias, embora dialoguem com suas questões.","A linguagem articula sofrimento social e elaboração poética, com imagens, oralidade e associações entre palavras. A escrevivência ajuda a compreender essa escrita: experiências pessoais e coletivas alimentam a ficção, sem transformá-la automaticamente em autobiografia literal. O livro permite perceber pessoas que desejam, lembram, amam e resistem, além das agressões que sofrem. Para estudar, observe como voz narrativa, imagens e memória produzem sentidos, evitando ler cada história apenas como exemplo de um problema social."],"themes":[{"title":"Memória e ancestralidade","text":"Recordar liga a experiência íntima a histórias coletivas; no conto-título, a relação entre filha e mãe organiza esse reconhecimento."},{"title":"Mulheres e maternidades","text":"A presença de diferentes mães e filhas amplia a representação da mulher negra e evita um modelo único de experiência feminina."},{"title":"Violência e subjetividade","text":"A denúncia da exclusão convive com afetos e desejos. As personagens não se resumem à condição de vítimas."}],"focus":["Diferencie o conto de abertura da coletânea: não há uma protagonista comum às quinze histórias.","Relacione o trabalho poético da linguagem às situações sociais narradas, sem separar forma e conteúdo.","Leia escrevivência como diálogo entre experiência, memória coletiva e invenção literária."],"pitfalls":["Tratar todos os contos como depoimentos factuais da autora.","Concluir que a presença da violência elimina o amor, a esperança e a capacidade de ação das personagens."],"sources":[{"title":"Pallas — apresentação editorial de Olhos d'água","url":"https://pallaseditora.com.br/produto/olhos-d-agua/"},{"title":"Itaú Cultural — Escrevivência e bibliografia de Conceição Evaristo","url":"https://www.itaucultural.org.br/ocupacao/conceicao-evaristo/escrevivencia/"},{"title":"UFMG / Literafro — conto Olhos d'água","url":"https://www.letras.ufmg.br/literafro/24-textos-das-autoras/929-conceicao-evaristoolhos-d-agua"},{"title":"Silva e Conte — O vaivém das memórias em Olhos d'água (Fólio)","url":"https://periodicos2.uesb.br/folio/article/view/5527"},{"title":"Nóbrega — Escrevivência, mulheres e mães (UFCG)","url":"https://revistas.editora.ufcg.edu.br/index.php/r15o/article/view/6951"}],"questions":[{"id":"olhos-dagua-01","prompt":"No conto de abertura, a busca pela cor dos olhos da mãe organiza lembranças da narradora. Qual leitura explica melhor a função dessa pergunta?","options":["Ela transforma uma investigação física em reconhecimento afetivo e ancestral.","Ela estabelece um mistério policial resolvido por testemunhas externas.","Ela demonstra que a narradora deseja apagar as experiências da infância.","Ela substitui as questões sociais por uma descrição exclusivamente biológica.","Ela comprova que o parentesco depende da semelhança da cor dos olhos."],"answerIndex":0,"explanation":"A pergunta aciona lembranças de cuidados e dificuldades, fazendo da imagem materna uma via de pertencimento. Seu alcance ultrapassa a identificação de um traço físico.","skill":"Interpretação de motivo narrativo"},{"id":"olhos-dagua-02","prompt":"A presença de narrativas e protagonistas diversas em Olhos d'água produz qual efeito de conjunto?","options":["Organiza uma trajetória contínua, cuja narradora reaparece em todos os capítulos.","Constrói um mosaico de experiências negras, sem apagar diferenças entre as personagens.","Elimina relações temáticas entre histórias que devem ser lidas como documentos isolados.","Faz cada protagonista representar de maneira idêntica todas as mulheres brasileiras.","Subordina as histórias femininas a uma única personagem masculina central."],"answerIndex":1,"explanation":"O formato de coletânea admite autonomia e diálogo entre os contos. Experiências relacionadas pela desigualdade não tornam as personagens equivalentes nem criam uma protagonista única.","skill":"Composição da coletânea"},{"id":"olhos-dagua-03","prompt":"Ao relacionar escrevivência e ficção em Olhos d'água, qual procedimento de leitura é mais adequado?","options":["Atribuir à autora todas as ações praticadas pelas narradoras.","Desconsiderar a experiência coletiva para preservar a autonomia da arte.","Reconhecer a transformação estética de experiências individuais e coletivas.","Classificar cada conto como registro jornalístico verificável.","Supor que as diferenças entre narrador e personagem deixam de existir."],"answerIndex":2,"explanation":"Escrevivência aproxima escrita e experiência, mas não dissolve a criação ficcional. Memórias e vivências podem ser reelaboradas por narradores, imagens e situações inventadas.","skill":"Conceito literário e autoria"},{"id":"olhos-dagua-04","prompt":"Na leitura da coletânea, como se relacionam a dureza das situações narradas e a linguagem poética?","options":["As imagens substituem a denúncia por uma idealização da pobreza.","O lirismo torna desnecessário observar quem sofre ou exerce a violência.","A denúncia exige a ausência de metáforas e de recursos expressivos.","A elaboração poética amplia a percepção dos afetos e das experiências sociais.","A poeticidade converte os acontecimentos em episódios sem dimensão histórica."],"answerIndex":3,"explanation":"A forma poética participa da construção de sentido: torna sensíveis relações, lembranças e dores. Ela pode intensificar a crítica social, em vez de neutralizá-la.","skill":"Relação entre forma e conteúdo"},{"id":"olhos-dagua-05","prompt":"Por que a presença de mulheres negras em diferentes idades e circunstâncias é relevante para a interpretação do livro?","options":["Porque permite substituir a leitura dos contos por uma biografia coletiva uniforme.","Porque demonstra que as diferenças de geração não alteram as experiências.","Porque restringe a identidade de cada personagem ao seu papel de mãe.","Porque afasta da obra as relações entre gênero e desigualdade racial.","Porque amplia possibilidades de representação e contraria imagens estereotipadas."],"answerIndex":4,"explanation":"A variedade de experiências revela subjetividades específicas. A obra dá densidade às personagens, evitando que uma função social ou um estereótipo esgote sua identidade.","skill":"Representação literária"},{"id":"olhos-dagua-06","prompt":"Um leitor afirma que recordar o passado, em Olhos d'água, serve apenas para interromper a ação presente. Qual argumento melhor revê essa leitura?","options":["As recordações substituem as personagens por explicações históricas impessoais.","A memória interfere no reconhecimento de si e liga tempos e experiências coletivas.","As lembranças garantem que todas as narradoras ofereçam versões objetivas dos fatos.","O passado estabelece uma origem capaz de resolver definitivamente todos os conflitos.","O retorno temporal serve para comprovar a ausência de mudanças na sociedade."],"answerIndex":1,"explanation":"A memória tem função estruturante e identitária. As relações entre passado e presente ajudam a construir sujeitos e pertencimentos, sem garantir objetividade ou solução definitiva.","skill":"Temporalidade e memória"},{"id":"olhos-dagua-07","prompt":"A imagem da água no conto-título pode articular choro, lembrança e ancestralidade. Que procedimento interpretativo sustenta essa leitura?","options":["Restringir a água ao significado meteorológico, excluindo o contexto afetivo.","Procurar um código no qual cada elemento tenha sempre uma única tradução.","Desconsiderar os vínculos entre a narradora e a figura materna.","Examinar como a imagem ganha sentidos nas relações construídas pela narrativa.","Atribuir à imagem qualquer significado, independentemente das cenas narradas."],"answerIndex":3,"explanation":"O símbolo é interpretado em contexto. A relação entre olhos, lágrimas e memória materna sustenta associações de sentido, sem autorizar significados arbitrários ou uma tradução única.","skill":"Imagem e simbolismo"},{"id":"olhos-dagua-08","prompt":"Ao estudar as maternidades na coletânea, qual hipótese deve orientar uma comparação entre personagens?","options":["A maternidade é vivida sob condições diferentes e não apaga a singularidade das mulheres.","As mães exercem sempre a mesma função narrativa, qualquer que seja o conto.","Os vínculos familiares tornam irrelevantes as condições de trabalho e de moradia.","A identidade das personagens pode ser integralmente explicada pelo instinto materno.","O afeto materno garante proteção suficiente contra a violência social."],"answerIndex":0,"explanation":"A comparação deve preservar diferenças entre mulheres e contextos. Reconhecer a importância da maternidade não significa explicá-la como experiência homogênea nem isolá-la das desigualdades.","skill":"Comparação temática"},{"id":"olhos-dagua-09","prompt":"Um resumo apresenta Olhos d'água como 'a história de uma filha que procura a cor dos olhos da mãe'. Qual é a principal limitação desse resumo?","options":["Confunde o livro com um romance ambientado fora do Brasil.","Atribui um narrador em terceira pessoa ao conto de abertura.","Toma o enredo de um conto como se fosse o enredo de toda a coletânea.","Elimina a pergunta que movimenta o conto-título.","Confunde a autoria de Conceição Evaristo com a de uma personagem."],"answerIndex":2,"explanation":"A descrição corresponde ao conto que abre e nomeia o livro. A coletânea reúne outras histórias e não pode ser resumida por uma única sequência de acontecimentos.","skill":"Distinção entre parte e todo"},{"id":"olhos-dagua-10","prompt":"Se uma análise destaca apenas as agressões sofridas pelas personagens, que dimensão importante da coletânea ela tende a perder?","options":["A comprovação de que os conflitos são exclusivamente individuais.","A superioridade moral de todas as protagonistas sobre as demais personagens.","A neutralidade dos narradores diante das relações sociais.","A ausência de vínculos entre memória e identidade.","A complexidade de sujeitos que também constroem afetos, desejos e formas de resistência."],"answerIndex":4,"explanation":"A violência é central, mas não esgota as vidas representadas. Considerar afetos, desejos e resistência evita reproduzir a redução das personagens à condição de vítimas.","skill":"Leitura crítica de interpretação"}],"color":"#486e81"},{"id":"vila-sapo","title":"Vila Sapo","author":"José Falero","year":2019,"genre":"Contos","tagline":"A periferia de Porto Alegre como espaço de linguagem, conflito e humanidade.","bibliographicNote":"Primeira publicação em 2019, pela Venas Abiertas. A edição da Todavia é de 2022 e acrescenta um conto; por isso, a quantidade de contos varia entre edições.","summary":["Vila Sapo é a coletânea de estreia de José Falero, publicada em 2019. Suas histórias se organizam em torno de uma comunidade real da periferia de Porto Alegre. Trabalhadores, mães, jovens e pessoas envolvidas no crime integram esse universo de desigualdade social e racial. Não existe um único enredo que atravesse o volume: os contos compõem perspectivas distintas sobre vidas marcadas por precariedade, conflitos e tentativas de sobrevivência.","O território não funciona apenas como fundo para acontecimentos violentos. As relações entre pessoas, as formas de falar e os modos de avaliar a vida dão espessura ao espaço narrado. A proximidade com a experiência periférica desloca o olhar que costuma enxergar a favela de fora. Amizade, desejo, amor, humor e reflexão convivem com o perigo. Esses elementos permitem ler as personagens como sujeitos complexos, sem transformar suas ações em exemplos moralmente simples.","A escrita combina marcas de oralidade e elaboração literária. Os registros de fala participam da construção das vozes e do ritmo, não constituem falhas a serem corrigidas pelo leitor. A crítica social depende também da forma dos relatos, das escolhas de perspectiva e das tensões que permanecem abertas. Para a prova, vale investigar como linguagem e território se articulam, distinguindo a voz de cada narrador da posição do autor e evitando reduzir o livro a um documento sobre criminalidade."],"themes":[{"title":"Território e desigualdade","text":"A comunidade concentra relações locais que permitem refletir sobre a segregação urbana e a distribuição desigual de oportunidades."},{"title":"Vozes e oralidade","text":"A construção de falas e registros aproxima o leitor do universo narrado e participa do trabalho estético dos contos."},{"title":"Dignidade e contradição","text":"Afetos, reflexão e conflito coexistem. Humanizar uma personagem não exige considerá-la inocente nem aprovar suas ações."}],"focus":["Observe quem narra e como o registro de linguagem situa a voz no universo social do conto.","Relacione espaço e relações de poder, em vez de usar a periferia como explicação automática de toda conduta.","Compare a crítica à desigualdade com os afetos e desejos que impedem reduzir personagens a estereótipos."],"pitfalls":["Confundir Vila Sapo, livro de contos, com o romance Os supridores.","Interpretar marcas de oralidade como incapacidade do autor ou supor que todo narrador expressa sua opinião pessoal."],"sources":[{"title":"Todavia — apresentação editorial e dados de edição de Vila Sapo","url":"https://todavialivros.com.br/livros/vila-sapo"},{"title":"Literatura RS — José Falero e a legitimação de uma visão de mundo (2019)","url":"https://literaturars.com.br/2019/04/06/jose-falero-e-a-legitimacao-de-uma-visao-de-mundo/"},{"title":"Guto Leite / Matinal — Vila Sapo, de José Falero","url":"https://www.matinaljornalismo.com.br/parentese/guto-leite-vila-sapo-de-jose-falero/"},{"title":"Andrea Kahmann / Aletria-UFMG — A literatura trânsfuga de José Falero","url":"https://periodicos.ufmg.br/index.php/aletria/article/view/29268"},{"title":"Matinal — entrevista com José Falero: Todo vontades","url":"https://www.matinaljornalismo.com.br/parentese/entrevista/jose-falero-todo-vontades/"}],"questions":[{"id":"vila-sapo-01","prompt":"Em Vila Sapo, por que a comunidade pode ser interpretada como mais que um cenário?","options":["Porque elimina as diferenças individuais entre seus moradores.","Porque determina biologicamente as ações das personagens.","Porque articula linguagem, vínculos e condições de vida que participam dos conflitos.","Porque substitui a necessidade de construir narradores e perspectivas.","Porque mantém os acontecimentos isolados das desigualdades brasileiras."],"answerIndex":2,"explanation":"O espaço é socialmente construído: relações, oportunidades e modos de falar integram a experiência narrada. Ele participa dos sentidos, sem determinar mecanicamente cada personagem.","skill":"Espaço narrativo"},{"id":"vila-sapo-02","prompt":"Como avaliar o emprego de oralidade nos contos de José Falero?","options":["Como escolha expressiva que constrói vozes, ritmo e pertencimento social.","Como ausência de revisão, sem efeitos sobre a interpretação.","Como reprodução neutra de uma fala idêntica em todas as periferias.","Como recurso que impede a existência de linguagem literária elaborada.","Como sinal de que autor, narrador e personagem são a mesma pessoa."],"answerIndex":0,"explanation":"Marcas de fala podem resultar de elaboração estética. Elas ajudam a caracterizar vozes e relações sociais; não permitem confundir autoria e narração nem uniformizar experiências periféricas.","skill":"Variação linguística e estilo"},{"id":"vila-sapo-03","prompt":"Uma análise afirma que Vila Sapo 'se limita a mostrar criminalidade'. Qual elemento do conjunto mais diretamente questiona essa leitura?","options":["O abandono dos conflitos sociais em favor de um mundo idealizado.","A organização de todos os contos como etapas de uma investigação.","A exclusão das personagens vinculadas ao trabalho e à família.","A substituição dos acontecimentos por descrições geográficas.","A coexistência de perigo, amizade, amor, humor e reflexão nas vidas narradas."],"answerIndex":4,"explanation":"A pluralidade humana excede a criminalidade. Afetos e reflexões convivem com a violência, produzindo personagens e relações que não cabem em uma única categoria social.","skill":"Representação e estereótipos"},{"id":"vila-sapo-04","prompt":"Ao estudar uma reflexão moral formulada por um narrador de Vila Sapo, qual cuidado é necessário?","options":["Considerá-la correta por decorrer de uma experiência de sofrimento.","Atribuí-la ao autor, pois a ficção elimina mediações entre ambos.","Ignorá-la, porque personagens de contos não elaboram ideias.","Examinar sua perspectiva e suas contradições sem identificá-la automaticamente com o autor.","Substituí-la por uma regra moral externa antes de ler a situação narrada."],"answerIndex":3,"explanation":"Narradores têm posições e limites próprios. A análise deve relacionar suas ideias às situações e à construção da voz, preservando a distinção entre instância narrativa e autoria.","skill":"Autor e narrador"},{"id":"vila-sapo-05","prompt":"A apresentação editorial aproxima Vila Sapo de outras periferias brasileiras. Qual leitura preserva melhor a relação entre local e coletivo?","options":["A experiência de Porto Alegre reproduz sem diferenças qualquer outra comunidade.","A especificidade do território permite discutir estruturas de desigualdade mais amplas.","O valor coletivo depende de eliminar particularidades locais da linguagem.","Os conflitos só têm sentido para moradores que conhecem pessoalmente o lugar.","A comunidade é um espaço abstrato, sem vínculos com uma cidade real."],"answerIndex":1,"explanation":"Uma experiência local pode iluminar processos amplos, como segregação e desigualdade. Isso não torna as periferias idênticas nem exige apagar as particularidades do território representado.","skill":"Relação entre particular e social"},{"id":"vila-sapo-06","prompt":"Por que humanizar uma personagem envolvida em violência não equivale a justificar todas as suas ações?","options":["Porque a análise literária deve excluir as consequências dos atos narrados.","Porque as condições sociais tornam impossível qualquer avaliação de conduta.","Porque personagens complexas deixam de participar de relações de poder.","Porque a presença de afetos comprova que nenhum dano foi produzido.","Porque compreender motivos e contradições difere de conceder aprovação moral."],"answerIndex":4,"explanation":"A complexidade narrativa permite compreender sujeitos e condições sem absolvição automática. Ações podem ser criticadas ao mesmo tempo que se reconhecem afetos, razões e conflitos de quem as pratica.","skill":"Complexidade da personagem"},{"id":"vila-sapo-07","prompt":"Alguns contos não encerram todas as tensões apresentadas. Que efeito essa escolha pode produzir em Vila Sapo?","options":["A certeza de que conflitos sociais se resolvem fora de cena.","A revelação de que o texto perdeu necessariamente suas páginas finais.","A recusa de uma solução reconfortante e a permanência de questões para o leitor.","A transformação automática de toda narrativa em reportagem incompleta.","A ausência de qualquer organização estética dos acontecimentos."],"answerIndex":2,"explanation":"A abertura pode ser uma escolha formal: sustenta a inquietação e evita oferecer resolução fácil para experiências contraditórias. Desfecho aberto não equivale a falta de elaboração.","skill":"Desfecho e efeito de leitura"},{"id":"vila-sapo-08","prompt":"Qual procedimento é mais adequado para relacionar denúncia social e valor literário nos contos?","options":["Observar como perspectiva, linguagem e composição produzem a crítica da realidade.","Avaliar o valor da obra apenas pela gravidade dos problemas mencionados.","Separar integralmente a forma narrativa do universo social representado.","Ler os relatos como provas estatísticas sobre a população periférica.","Usar a origem social do escritor como substituto da análise textual."],"answerIndex":0,"explanation":"A crítica social se realiza por escolhas formais, não apenas pelos assuntos. Considerar voz, composição e linguagem evita reduzir a literatura a documento ou julgar sua qualidade pela biografia do autor.","skill":"Forma literária e crítica social"},{"id":"vila-sapo-09","prompt":"Qual afirmação caracteriza corretamente a organização de Vila Sapo?","options":["É um romance em que duas personagens centrais conduzem todos os capítulos.","É uma autobiografia que exige equivalência factual entre autor e narradores.","É uma sequência de crônicas jornalísticas centradas em comentários de notícias.","É uma coletânea de contos relacionados por um universo social, com autonomia narrativa.","É uma narrativa única cujo enredo se confunde com o de Os supridores."],"answerIndex":3,"explanation":"Vila Sapo reúne contos e não deve ser confundido com Os supridores, romance de Falero. Relações de espaço e temática não eliminam a autonomia das histórias.","skill":"Gênero e organização"},{"id":"vila-sapo-10","prompt":"A leitura de personagens periféricas como sujeitos de conhecimento, e não apenas como objetos de observação, implica reconhecer que elas: ","options":["Fornecem uma versão neutra e definitiva da sociedade.","Elaboram interpretações da vida a partir de experiências próprias e contraditórias.","Representam a opinião uniforme de todos os moradores da comunidade.","Ficam dispensadas de conflitos e de responsabilidade por suas escolhas.","Só podem ser compreendidas mediante a correção de suas formas de falar."],"answerIndex":1,"explanation":"As vozes dos contos interpretam o mundo em vez de apenas ilustrá-lo. Reconhecer essa capacidade não significa torná-las neutras, infalíveis ou representantes homogêneas de um grupo.","skill":"Perspectiva e produção de sentido"}],"color":"#7e6847"},{"id":"ritos-passagem","title":"Ritos de passagem","author":"Ana Paula Tavares","year":1985,"genre":"Poesia angolana","tagline":"Corpo, memória e transformação em imagens da natureza.","summary":["Publicado em 1985, o primeiro livro de Ana Paula Tavares reúne poemas, sem desenvolver um enredo contínuo. A composição aproxima sensações, frutos, corpo e experiências femininas. Depois de um poema de abertura, três conjuntos articulam essa travessia: De cheiro macio ao tacto, Navegação circular e Cerimônias de passagem. A leitura acompanha mudanças e tensões, e não a trajetória de uma única personagem.","Frutos e outros elementos naturais ganham sentidos que ultrapassam a descrição da paisagem: evocam amadurecimento, desejo, vulnerabilidade e potência. A linguagem sensorial aproxima o que se vê, toca, cheira e saboreia. O corpo feminino aparece como lugar de experiência e conhecimento. O erotismo participa da construção de uma voz que deseja falar por si, em vez de permanecer apenas como objeto do olhar alheio.","A memória cultural angolana, particularmente vinculada ao sul do país, alimenta os poemas. Entretanto, preservar vínculos com a tradição não equivale a aceitar todos os seus valores: o livro também põe em tensão costumes e limites impostos às mulheres. No contexto posterior à independência de Angola, a liberdade pode ser pensada para além da emancipação nacional. Para a prova, observe como imagens, ritmos e silêncios articulam pertencimento coletivo e autonomia individual."],"themes":[{"title":"Corpo e desejo","text":"O erotismo torna visíveis experiências e desejos femininos frequentemente silenciados."},{"title":"Natureza simbólica","text":"Frutos, sabores e texturas aproximam ciclos naturais e transformações humanas."},{"title":"Memória e contestação","text":"Os vínculos culturais coexistem com o questionamento de práticas que restringem a autonomia."}],"focus":["Relacione imagens sensoriais ao corpo e à construção da voz poética.","Diferencie valorização da memória de aceitação irrestrita da tradição.","Leia cada rito como transformação simbólica, sem procurar um enredo de romance."],"pitfalls":["Reduzir os frutos a decoração ou a descrição botânica literal.","Confundir a voz lírica com um depoimento biográfico direto da autora."],"sources":[{"title":"Revista Vértices / IFF — Ritos de passagem e (re)memória","url":"https://editoraessentia.iff.edu.br/index.php/vertices/article/view/16314"},{"title":"Mulemba / UFRJ — O corpo é possível","url":"https://www.revistas.ufrj.br/index.php/mulemba/article/view/31261"},{"title":"Cadernos Imbondeiro / UFPB — A condição feminina na poesia de Paula Tavares","url":"https://periodicos.ufpb.br/index.php/ci/article/view/21896"},{"title":"Via Atlântica / USP — Cerimônia, alquimia e iniciação","url":"https://revistas.usp.br/viaatlantica/pt_BR/article/view/224664"},{"title":"Repositório UNILAB — Primeira produção poética e crítica ao lugar do feminino","url":"https://repositorio.unilab.edu.br/jspui/handle/123456789/3223"}],"questions":[{"id":"ritos-passagem-01","prompt":"Ao aproximar o amadurecimento dos frutos das experiências do corpo, o livro constrói principalmente:","options":["Uma explicação científica dos processos hormonais.","Uma paisagem separada dos conflitos humanos.","Uma rede simbólica de desejo e transformação.","Uma oposição entre natureza pura e corpo impuro.","Um inventário agrícola de finalidade documental."],"answerIndex":2,"explanation":"As imagens naturais adquirem sentidos ligados à experiência humana. A aproximação é simbólica e sensorial: não transforma os poemas em tratados biológicos nem apaga as tensões vividas pelo sujeito.","skill":"Imagem e metáfora"},{"id":"ritos-passagem-02","prompt":"Qual leitura melhor expressa a relação de Ritos de passagem com a tradição?","options":["A memória cultural pode ser retomada e seus limites de gênero questionados.","A autonomia exige que toda memória comunitária seja abandonada.","Os costumes são apresentados como regras invariáveis e incontestáveis.","A tradição surge apenas como cenário exótico para um leitor estrangeiro.","A crítica aos costumes elimina o pertencimento cultural da voz poética."],"answerIndex":0,"explanation":"Pertencer e contestar não são atitudes incompatíveis. A poesia mobiliza referências culturais enquanto interroga o silenciamento e as restrições que podem atingir as mulheres nesses mesmos contextos.","skill":"Tradição e crítica"},{"id":"ritos-passagem-03","prompt":"A presença do erotismo no livro ganha força crítica porque:","options":["Substitui as questões culturais por uma descrição clínica.","Restringe a mulher ao papel de objeto observado.","Garante que todos os poemas tenham uma leitura autobiográfica.","Torna a experiência do desejo independente da linguagem.","Afirma experiências femininas e confronta o seu silenciamento."],"answerIndex":4,"explanation":"O desejo integra a elaboração de uma subjetividade que fala e conhece a si. A dimensão crítica nasce dessa afirmação, articulada à forma poética e às relações culturais.","skill":"Corpo e subjetividade"},{"id":"ritos-passagem-04","prompt":"Um estudante procura identificar protagonista, clímax e desfecho únicos no livro. Qual ajuste de leitura é mais adequado?","options":["Trocar a ordem dos poemas para recuperar a cronologia perdida.","Buscar relações entre imagens e conjuntos poéticos, sem exigir enredo contínuo.","Tratar cada título como uma data da vida da autora.","Identificar o último poema como solução de todos os conflitos anteriores.","Ler as divisões como capítulos de uma autobiografia documental."],"answerIndex":1,"explanation":"A unidade de uma coletânea poética pode resultar da recorrência e transformação de imagens. Ela não depende da sequência de acontecimentos esperada em certas narrativas.","skill":"Gênero e composição"},{"id":"ritos-passagem-05","prompt":"A associação entre cheiro, sabor e tato, recorrente na leitura da obra, contribui para:","options":["Eliminar a participação do leitor na produção de sentidos.","Fixar um significado botânico para cada poema.","Garantir uma descrição objetiva sem ambiguidades.","Materializar sensorialmente experiências do corpo e do mundo.","Separar a paisagem da experiência da voz lírica."],"answerIndex":3,"explanation":"A experiência sensorial torna corpo e ambiente próximos. Ao explorar diferentes percepções, o poema pode sugerir desejo e transformação sem apresentar uma explicação abstrata e única.","skill":"Linguagem sensorial"},{"id":"ritos-passagem-06","prompt":"No contexto de Angola após a independência, a atenção às experiências femininas permite perceber que:","options":["A liberdade nacional resolve automaticamente toda desigualdade.","O livro abandona as relações entre indivíduo e coletividade.","A emancipação coletiva pode coexistir com restrições que ainda precisam ser enfrentadas.","Os poemas descrevem uma sociedade sem conflitos culturais.","A leitura histórica torna dispensável observar a forma dos poemas."],"answerIndex":2,"explanation":"A independência oferece um contexto importante, mas não explica nem resolve sozinha as relações de gênero. A poesia evidencia tensões entre pertencimento coletivo e liberdade do sujeito.","skill":"Contexto histórico"},{"id":"ritos-passagem-07","prompt":"Ao interpretar a voz que deseja, lembra ou protesta nos poemas, é mais rigoroso:","options":["Considerá-la uma construção poética, sem igualá-la automaticamente à pessoa da autora.","Tomar cada afirmação como registro verificável da vida de Ana Paula Tavares.","Atribuir a mesma identidade estável a todas as vozes de qualquer poema.","Ignorar as imagens para descobrir apenas informações biográficas.","Supor que uma voz feminina impede qualquer elaboração ficcional."],"answerIndex":0,"explanation":"O sujeito lírico é produzido pela linguagem do poema. A biografia pode contextualizar a leitura, mas não autoriza converter todas as imagens e situações em fatos pessoais.","skill":"Voz lírica"},{"id":"ritos-passagem-08","prompt":"Qual interpretação do título Ritos de passagem é mais produtiva para a leitura do conjunto?","options":["Ele promete um manual completo de cerimônias angolanas.","Ele indica uma viagem geográfica narrada em ordem cronológica.","Ele designa exclusivamente a passagem da vida para a morte.","Ele anuncia a substituição total da memória pelo presente.","Ele sugere transformações de existência, corpo e posição no mundo."],"answerIndex":4,"explanation":"As passagens abrangem mudanças de experiência e de condição. O título favorece a leitura simbólica das transformações, sem reduzir a coletânea a um catálogo etnográfico ou a um único rito.","skill":"Título e unidade"},{"id":"ritos-passagem-09","prompt":"Dizer que os frutos representam uma natureza feminina fixa e universal empobrece a leitura porque:","options":["O livro evita qualquer imagem ligada à natureza.","Transforma relações poéticas e culturais em uma essência biológica invariável.","O sentido figurado dispensa o contexto dos poemas.","A presença de frutos elimina a possibilidade de interpretação simbólica.","Os poemas apresentam uma tese científica sobre diferenças sexuais."],"answerIndex":1,"explanation":"A metáfora aproxima campos de experiência, mas não precisa estabelecer uma essência. É necessário observar o poema e o contexto para perceber tensão, desejo e construção de sentidos.","skill":"Leitura crítica"},{"id":"ritos-passagem-10","prompt":"Em uma resposta de prova sobre a autonomia feminina no livro, qual procedimento oferece a melhor sustentação?","options":["Citar apenas a nacionalidade da escritora.","Enumerar todos os frutos mencionados, sem interpretá-los.","Pressupor que o tema dispensa análise da linguagem.","Relacionar escolhas da voz poética e imagens do corpo às restrições culturais.","Resumir os poemas como episódios sucessivos de uma mesma personagem."],"answerIndex":3,"explanation":"Uma interpretação consistente articula forma e tema. As imagens e a posição da voz ajudam a demonstrar como desejo, memória e limites sociais se relacionam no texto.","skill":"Argumentação interpretativa"}],"color":"#8d5e6e"},{"id":"utero-punho","title":"Um útero é do tamanho de um punho","author":"Angélica Freitas","year":2012,"genre":"Poesia brasileira contemporânea","tagline":"Humor e experimentação desmontam os modelos prontos de mulher.","bibliographicNote":"A primeira publicação é de 2012, pela Cosac Naify, conforme a editora atual. O ano de 2013 aparece na ficha da segunda reimpressão da Cosac Naify; não corresponde ao lançamento original. A edição da Companhia das Letras é de 2017.","summary":["Em seu segundo livro, Angélica Freitas reúne poemas que interrogam os modelos de mulher produzidos pela sociedade. Não há uma protagonista ou história linear: a unidade vem do diálogo entre textos, vozes e procedimentos. O conjunto inclui sete partes, entre elas Uma mulher limpa, A mulher é uma construção, o poema que dá título ao volume e 3 poemas com o auxílio do Google.","O livro trabalha com frases corriqueiras, rótulos, repetições e situações absurdas. Em vez de oferecer uma definição correta e definitiva do feminino, expõe as contradições das definições que circulam como evidências. Humor e ironia deslocam expectativas sobre aparência, comportamento, sexualidade e maternidade. A linguagem coloquial aproxima esses mecanismos do cotidiano, enquanto montagens e jogos verbais mostram que as palavras também participam da produção das normas.","No poema-título, o corpo torna-se terreno de disputa entre discursos que pretendem explicá-lo, controlá-lo ou determinar sua utilidade. A obra pergunta quem pode falar e decidir sobre esse corpo. A invenção formal é central: verso livre, reaproveitamento de falas e pesquisa na internet não são enfeites de uma mensagem pronta. Eles fazem o leitor estranhar o que parecia normal. Para a prova, diferencie a voz que reproduz um preconceito do efeito crítico produzido pela composição."],"themes":[{"title":"Normas de gênero","text":"Definições aparentemente naturais do feminino revelam convenções e exigências sociais."},{"title":"Corpo e autonomia","text":"A capacidade reprodutiva não esgota a identidade nem autoriza o controle externo do corpo."},{"title":"Humor e montagem","text":"A repetição e o absurdo reorganizam falas conhecidas para expor suas contradições."}],"focus":["Identifique quem fala e que efeito surge quando uma frase preconceituosa é repetida.","Relacione o humor à crítica, observando também seus efeitos de desconforto.","Analise como a apropriação de discursos cotidianos constrói o poema."],"pitfalls":["Confundir a encenação irônica de um estereótipo com sua defesa pela autora.","Ler o livro como se propusesse uma identidade feminina única e determinada pela anatomia."],"sources":[{"title":"Companhia das Letras — apresentação e ficha editorial","url":"https://www.companhiadasletras.com.br/livro/9788535929829/um-utero-e-do-tamanho-de-um-punho"},{"title":"Estudos Linguísticos / GEL — Interdições do feminino","url":"https://revistas.gel.org.br/estudos-linguisticos/article/view/1058"},{"title":"Opiniães / USP — Uma leitura da obra como máquina performática","url":"https://revistas.usp.br/opiniaes/article/view/165812"},{"title":"Repositório UFC — O feminismo e o feminino na obra","url":"https://repositorio.ufc.br/handle/riufc/60036"},{"title":"Livraria da Travessa — ficha da reimpressão de 2013","url":"https://www.travessa.com.br/um-utero-e-do-tamanho-de-um-punho/artigo/187239bc-67f2-4088-95b8-91c6ed9f59f7"}],"questions":[{"id":"utero-punho-01","prompt":"Ao repetir exigências sobre como uma mulher deve parecer e agir, os poemas tendem a:","options":["Organizar conselhos que o leitor deve seguir literalmente.","Confirmar a origem puramente biológica dessas exigências.","Transformar normas de comportamento em leis naturais.","Expor, pelo deslocamento e pelo humor, o caráter construído dessas exigências.","Defender a neutralidade de qualquer frase cotidiana."],"answerIndex":3,"explanation":"A repetição pode tornar estranha uma afirmação aparentemente normal. O efeito crítico depende da composição e do contexto, não da aceitação literal da fala reproduzida.","skill":"Ironia e repetição"},{"id":"utero-punho-02","prompt":"Qual leitura melhor explica a presença de discursos médicos, religiosos e publicitários no poema-título?","options":["São garantias de que a descrição do corpo é neutra.","Evidenciam vozes e instituições que disputam a autoridade sobre o corpo.","Formam uma sequência cronológica da história da medicina.","Servem apenas para demonstrar o vocabulário da poeta.","Retiram do poema qualquer relação com a vida social."],"answerIndex":1,"explanation":"A montagem faz conviver falas de origens diferentes. Essa circulação mostra como o corpo pode ser definido e regulado por outros, abrindo a questão da autonomia de quem o vive.","skill":"Montagem de discursos"},{"id":"utero-punho-03","prompt":"A presença do absurdo e do riso não diminui necessariamente a dimensão crítica do livro porque:","options":["O humor garante que qualquer frase tenha um sentido único.","Uma situação engraçada torna o conflito social irrelevante.","O absurdo comprova que os poemas não dialogam com a realidade.","A comicidade substitui toda elaboração formal por improvisação.","O estranhamento pode revelar a falta de sentido de normas naturalizadas."],"answerIndex":4,"explanation":"O riso pode produzir desconforto e reflexão. O nonsense desarranja expectativas e torna perceptível o caráter contraditório de falas sobre o feminino.","skill":"Humor e crítica"},{"id":"utero-punho-04","prompt":"Ao estudar os poemas compostos com auxílio do Google, o leitor deve considerar principalmente:","options":["A seleção e a montagem de falas que circulam socialmente.","A confirmação estatística de uma essência feminina.","A substituição de toda decisão estética por um algoritmo.","A garantia de que o conteúdo encontrado na internet é verdadeiro.","A eliminação de qualquer relação entre poema e contexto."],"answerIndex":0,"explanation":"Pesquisar não equivale a aceitar os resultados como verdade. A organização do material apropriado integra o trabalho poético e pode expor padrões da linguagem social.","skill":"Apropriação e autoria"},{"id":"utero-punho-05","prompt":"Uma leitura do título que considere o conjunto da obra deve evitar:","options":["Relacionar corpo e linguagem na construção dos poemas.","Perceber que o corpo pode se tornar objeto de controle.","Reduzir a identidade feminina à função reprodutiva.","Interpretar a comparação como ponto de partida para novos sentidos.","Observar as relações entre o título e as vozes do poema."],"answerIndex":2,"explanation":"O livro problematiza a redução da pessoa à anatomia e à maternidade. A referência ao órgão não impõe uma essência: permite examinar discursos que tentam fixá-la.","skill":"Título e corpo"},{"id":"utero-punho-06","prompt":"Verso livre, linguagem coloquial e montagem de frases conhecidas contribuem para:","options":["Eliminar a diferença entre um poema e qualquer anotação casual.","Tornar obrigatório um mesmo ritmo em todo o livro.","Impedir que referências cotidianas adquiram outro sentido.","Produzir efeitos de voz e ritmo que participam da crítica.","Separar completamente a experimentação formal dos temas."],"answerIndex":3,"explanation":"A forma organiza o modo como as vozes são ouvidas. Ritmos, cortes e combinações transformam falas usuais em matéria de estranhamento e reflexão.","skill":"Forma e sentido"},{"id":"utero-punho-07","prompt":"Um leitor afirma que a autora concorda com uma frase preconceituosa porque ela aparece em um poema. A principal falha desse argumento é:","options":["Exigir atenção ao contexto da frase.","Ignorar a distância possível entre fala encenada e efeito irônico do texto.","Reconhecer que há diferentes vozes na linguagem.","Considerar que um poema pode produzir crítica social.","Perceber que a escolha das palavras interfere no sentido."],"answerIndex":1,"explanation":"A inclusão de uma fala não implica adesão a ela. É preciso observar exageros, repetições, contrastes e o conjunto para reconhecer o alvo da ironia.","skill":"Voz e posicionamento"},{"id":"utero-punho-08","prompt":"A reunião de poemas sobre diferentes modelos de mulher permite interpretar o livro como:","options":["Um manual que fixa a conduta ideal para todas as mulheres.","Uma autobiografia em que cada voz representa a mesma pessoa.","Uma descrição do feminino sem relação com linguagem ou sociedade.","Uma defesa de que a aparência revela uma identidade definitiva.","Uma investigação crítica de classificações que tentam enquadrar sujeitos."],"answerIndex":4,"explanation":"Os rótulos são postos em circulação e em crise. O conjunto evidencia a insuficiência das classificações, em vez de substituí-las por um modelo obrigatório.","skill":"Unidade temática"},{"id":"utero-punho-09","prompt":"Qual situação de leitura permite reconhecer a passagem do estereótipo ao efeito crítico?","options":["Uma afirmação cotidiana parece familiar, mas sua repetição exagerada evidencia sua violência.","Uma afirmação cotidiana é aceita como descrição neutra da realidade.","Uma sequência de rimas impede o leitor de interpretar qualquer ideia.","Um poema é lido apenas para localizar dados biográficos.","Uma expressão social é considerada verdadeira por aparecer várias vezes."],"answerIndex":0,"explanation":"O deslocamento pode expor aquilo que o uso habitual esconde. Ao tornar perceptível a violência de uma fórmula, o poema modifica a relação do leitor com ela.","skill":"Efeito de estranhamento"},{"id":"utero-punho-10","prompt":"Para analisar a dimensão política da obra sem reduzir os poemas a uma mensagem pronta, é mais adequado:","options":["Ignorar os jogos verbais para descobrir uma palavra de ordem única.","Julgar o sentido apenas a partir do título do livro.","Mostrar como a organização das vozes e o humor interrogam normas de gênero.","Tratar o vocabulário coloquial como prova de ausência de elaboração.","Substituir a leitura dos poemas por informações sobre a autora."],"answerIndex":2,"explanation":"A crítica se realiza também nos procedimentos formais. Analisar a montagem, o tom e a circulação de falas permite compreender como o texto produz seus efeitos.","skill":"Análise integrada"}],"color":"#675b8d","listedYear":2013}];
